values ('bbbb0004-0000-4000-8000-000000000026', 'en', null, 'Neuroscience', 'How the nervous system builds behavior, from a single neuron firing to the circuits behind sensation, movement, memory, emotion, and sleep. Structure adapted from OpenStax Psychology 2e and MIT OpenCourseWare 9.01 Introduction to Neuroscience (CC BY / CC BY-NC-SA).', null, 'foundations', 26, true, 'science', '{}')
